package com.vandorlabs.client;

import com.google.gson.*;
import com.vandorlabs.blocks.*;
import com.vandorlabs.tiles.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.minecraft.block.BlockTrapDoor;
import net.minecraft.nbt.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.BlockPos;

/** Actual loaded tile relations, link repair and event-driven group power before native adaptation. */
public final class TrapdoorLifecycleLegacyChecks {
    private static final BlockPos ORIGIN=new BlockPos(15,80,8);
    private static NBTTagList members(List<BlockPos> cells){NBTTagList list=new NBTTagList();for(BlockPos cell:cells)list.appendTag(new NBTTagLong(cell.toLong()));return list;}
    private static JsonArray group(TileEntityProgrammableTrapdoor tile){JsonArray out=new JsonArray();for(TileEntityProgrammableTrapdoor leaf:tile.group())out.add(leaf.getPos().toLong());return out;}
    private static JsonObject snapshot(TileEntityProgrammableTrapdoor tile){JsonObject out=new JsonObject();out.add("group",group(tile));NBTTagCompound saved=tile.writeToNBT(new NBTTagCompound());out.addProperty("saved",saved.toString());out.addProperty("offset",tile.canOffsetClosedLeaf());out.addProperty("hinge",tile.motionHinge());out.addProperty("travel",tile.motionTravel());out.addProperty("overhang",tile.coverOverhang());if(tile instanceof TileEntityProgrammableDiagonalTrapdoor){TileEntityProgrammableDiagonalTrapdoor diagonal=(TileEntityProgrammableDiagonalTrapdoor)tile;try{out.addProperty("reverse",diagonal.rotationReverse());out.addProperty("closedReverse",diagonal.rotationReverse(Collections.emptyList()));out.addProperty("lift",diagonal.slideLiftDirection());}catch(ClassCastException invalid){out.addProperty("resolutionFailure",invalid.getClass().getSimpleName());}}return out;}
    public static void main(String[] args)throws Exception{
        net.minecraft.init.Bootstrap.register();com.vandorlabs.VandorLabs.proxy=new com.vandorlabs.CommonProxy();
        net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityProgrammableTrapdoor.class,new net.minecraft.util.ResourceLocation("vandorlabs","programmable_trapdoor"));
        net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityProgrammableDiagonalTrapdoor.class,new net.minecraft.util.ResourceLocation("vandorlabs","programmable_diagonal_trapdoor"));
        BlockProgrammableTrapdoor regular=new BlockProgrammableTrapdoor();BlockProgrammableDiagonalTrapdoor diagonalBlock=new BlockProgrammableDiagonalTrapdoor();JsonArray rows=new JsonArray();
        for(boolean diagonal:new boolean[]{false,true})for(int position=0;position<3;position++)for(EnumFacing face:EnumFacing.HORIZONTALS)for(int relation=0;relation<4;relation++)for(int fault=0;fault<11;fault++)for(int trigger=0;trigger<3;trigger++)for(int power=0;power<3;power++){
            NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);List<BlockPos> cells=new ArrayList<>();cells.add(ORIGIN);EnumFacing across=diagonal?face.rotateYCCW():EnumFacing.EAST,along=diagonal?(position==2?face.getOpposite():EnumFacing.UP):EnumFacing.SOUTH;
            if(relation==1)cells.add(ORIGIN.offset(across));if(relation>=2){cells.add(ORIGIN.offset(across));cells.add(ORIGIN.offset(along));cells.add(ORIGIN.offset(across).offset(along));}
            List<BlockPos> links=new ArrayList<>(cells);if(fault==4)links.remove(0);if(fault==5)links.add(ORIGIN);if(fault==6)while(links.size()<65)links.add(ORIGIN);
            JsonObject row=new JsonObject();row.addProperty("diagonal",diagonal);row.addProperty("position",position);row.addProperty("facing",face.getHorizontalIndex());row.addProperty("relation",relation);row.addProperty("fault",fault);row.addProperty("power",power);row.addProperty("trigger",trigger);JsonArray inputs=new JsonArray();List<TileEntityProgrammableTrapdoor> leaves=new ArrayList<>();
            for(int index=0;index<cells.size();index++){BlockPos at=cells.get(index);if(fault==1&&index==cells.size()-1&&index>0)continue;boolean leafDiagonal=fault==9&&index>0?!diagonal:diagonal;TileEntityProgrammableTrapdoor tile=leafDiagonal?new TileEntityProgrammableDiagonalTrapdoor():new TileEntityProgrammableTrapdoor();NBTTagCompound tag=new NBTTagCompound();tag.setInteger("x",at.getX());tag.setInteger("y",at.getY());tag.setInteger("z",at.getZ());tag.setInteger("housingTexture",ScreenHousingTextures.DEFAULT_TRAPDOOR);tag.setInteger("TrapdoorPosition",fault==8&&index>0?(position+1)%3:position);tag.setBoolean("TrapdoorSliding",fault==10&&index>0);tag.setInteger("TrapdoorTrigger",trigger);tag.setBoolean("ChannelSignal",power==1&&index==cells.size()-1);tag.setBoolean("TrapdoorCover",fault==7);tag.setInteger("TrapdoorCoverFacing",face.getHorizontalIndex());tag.setInteger("DiagonalFacing",face.getHorizontalIndex());tag.setInteger("DiagonalGroupFacing",face.getHorizontalIndex());tag.setBoolean("DiagonalReverse",index%2!=0);tag.setDouble("TrapdoorHinge",index==0?-.9375:1.9375);tag.setDouble("TrapdoorTravel",2.9375);if(relation==1)tag.setLong("TrapdoorPartner",cells.get(1-index).toLong());if(relation==2)tag.setLong("TrapdoorSquare",ORIGIN.toLong());if(relation==3)tag.setTag("TrapdoorAssembly",members(links));if(fault==2&&index>0){tag.removeTag("TrapdoorPartner");tag.removeTag("TrapdoorSquare");tag.removeTag("TrapdoorAssembly");}tile.readFromNBT(tag);tile.setWorld(world);tile.setPos(at);world.tiles.put(at,tile);world.states.put(at,(leafDiagonal?diagonalBlock:regular).getDefaultState().withProperty(BlockTrapDoor.FACING,face));inputs.add(tag.toString());leaves.add(tile);}
            world.chunkLimit=fault==3;if(power==2){BlockPos last=leaves.get(leaves.size()-1).getPos();for(EnumFacing direction:EnumFacing.values()){BlockPos source=last.offset(direction);if(!cells.contains(source)&&world.isBlockLoaded(source)){world.states.put(source,net.minecraft.init.Blocks.REDSTONE_BLOCK.getDefaultState());row.addProperty("physicalSource",source.toLong());break;}}}row.add("input",inputs);TileEntityProgrammableTrapdoor owner=leaves.get(0);row.add("before",snapshot(owner));owner.repairLinks();row.add("repaired",snapshot(owner));owner.evaluatePower(false);JsonArray result=new JsonArray();for(TileEntityProgrammableTrapdoor leaf:leaves)if(world.isBlockLoaded(leaf.getPos())){JsonObject end=new JsonObject();end.addProperty("pos",leaf.getPos().toLong());end.addProperty("open",world.getBlockState(leaf.getPos()).getValue(BlockTrapDoor.OPEN));end.addProperty("saved",leaf.writeToNBT(new NBTTagCompound()).toString());result.add(end);}row.add("powered",result);rows.add(row);
        }
        String json=rows.toString();StringBuilder hash=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(json.getBytes(StandardCharsets.UTF_8)))hash.append(String.format(Locale.ROOT,"%02x",b&255));if(rows.size()!=9504||!hash.toString().equals("50e1845571ec03524d1b4c670cd1765f52bfe6f0b3c9f5a3372e158a311e51fd"))throw new AssertionError("Released Trapdoor lifecycle changed "+hash);Path output=Paths.get(args[0]);Files.createDirectories(output.toAbsolutePath().getParent());Files.write(output,json.getBytes(StandardCharsets.UTF_8));System.out.println("Actual Trapdoor lifecycle PASS cases="+rows.size()+" golden="+hash);
    }
}
